import 'package:flutter/material.dart';import 'package:sehatak/core/models/child/child_models.dart';class ChildGrowthTrackerCard extends StatelessWidget{final ChildGrowthTracker? tracker;final Color accentColor;final VoidCallback? onTap;const ChildGrowthTrackerCard({super.key,this.tracker,this.accentColor=const Color(0xFF00BCD4),this.onTap});@override Widget build(BuildContext c){final birth=tracker?.birthDate;final age=birth==null?null:DateTime.now().difference(birth).inDays~/30;return Card(child:InkWell(onTap:onTap,borderRadius:BorderRadius.circular(16),child:Padding(padding:const EdgeInsets.all(16),child:Column(children:[Row(children:[Icon(Icons.child_care,color:accentColor,size:30),const SizedBox(width:10),const Expanded(child:Text('متابعة نمو الطفل',style:TextStyle(fontWeight:FontWeight.w800,fontSize:17))),const Icon(Icons.chevron_left)]),const SizedBox(height:14),Row(children:[_v('العمر',age==null?'--':'$age شهر'),_v('الطول',tracker?.height==null?'--':'${tracker!.height!.toStringAsFixed(1)} سم'),_v('الوزن',tracker?.weight==null?'--':'${tracker!.weight!.toStringAsFixed(1)} كجم')]))]))));}Widget _v(String a,String b)=>Expanded(child:Column(children:[Text(b,style:TextStyle(color:accentColor,fontWeight:FontWeight.w800,fontSize:16)),const SizedBox(height:3),Text(a,style:const TextStyle(fontSize:11))]));}}
